#define MAX_STEPS 100
#define MAX_DIST 100.
#define SURF_DIST .01

float sdBox(vec3 p, vec3 size) {
    vec3 d = abs(p) - size;
    return length(max(d, 0.)) + min(max(d.x, max(d.y, d.z)), 0.);
}

float getDist(vec3 p) {
    // Sphere definition (center x,y,z, radius)
    vec4 s = vec4(0, 1, 6, 1);

    // Box position and size
    vec3 boxPos = vec3(2, 1, 6);
    vec3 boxSize = vec3(0.5, 1, 0.5);

    float sphereDist = length(p - s.xyz) - s.w;
    float planeDist = p.y;
    float boxDist = sdBox(p - boxPos, boxSize);

    return min(min(sphereDist, planeDist), boxDist);
}

float RayMarch(vec3 ro, vec3 rd) {
    float d0 = 0.;

    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * d0;
        float dS = getDist(p);
        d0 += dS;
        if(d0 > MAX_DIST || dS < SURF_DIST) break;
    }

    return d0;
}

vec3 getNormal(vec3 p) {
    float d = getDist(p);
    vec2 e = vec2(.01, 0);

    vec3 n = d - vec3(
        getDist(p - e.xyy),
        getDist(p - e.yxy),
        getDist(p - e.yyx));

    return normalize(n);
}

float getLight(vec3 p) {
    vec3 lightPos = vec3(0, 5, 6);
    lightPos.xz += vec2(sin(iTime), cos(iTime)) * 2.;

    vec3 l = normalize(lightPos - p);
    vec3 n = getNormal(p);

    float dif = clamp(dot(n, l), 0., 1.);
    float d = RayMarch(p + n * SURF_DIST * 2., l);
    if(d < length(lightPos - p)) dif *= .1;

    return dif;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);

    // setting up the camera
    vec3 center = vec3(1, 0, 6); // center point of orbit (between sphere and box)
    float radius = 6.0;          // orbit radius
    float camHeight = 2.0;       
    float angle = iTime * 0.5;   

    // Calculate camera position - moving in a perfect circle at fixed height
    vec3 ro = vec3(
        center.x + radius * sin(angle),
        camHeight,                      // Constant height
        center.z + radius * cos(angle)
    );

    // Always look at the center point
    vec3 lookAt = center + vec3(0, 1, 0); // Look at height of 1 unit
    vec3 forward = normalize(lookAt - ro);
    vec3 right = normalize(cross(vec3(0, 1, 0), forward));
    vec3 up = cross(forward, right);

    // Create camera ray
    vec3 rd = normalize(forward + uv.x * right + uv.y * up);

    float d = RayMarch(ro, rd);
    vec3 p = ro + rd * d;

    float dif = getLight(p);
    col = vec3(dif);

    fragColor = vec4(col, 1.0);
}
